function sawBlade(name: string, position: Triple, radius: number, rotation: Triple = [0, 0, 90]): ModelPart {
  const outline = Array.from({ length: 64 }, (_, i): [number, number] => { const a = i * Math.PI / 32, r = radius * (i % 4 === 0 ? 1 : i % 4 === 1 ? .955 : .935); return [Math.cos(a) * r, Math.sin(a) * r]; });
  const bore = Array.from({ length: 12 }, (_, i): [number, number] => { const a = i * Math.PI / 6; return [Math.cos(a) * radius * .105, Math.sin(a) * radius * .105]; });
  return piercedPanel(name, position, outline, [bore], .004, material.steel, rotation);
}

function sawHood(name: string, position: Triple, radius: number, depth: number, rotation: Triple = [0, 90, 0]): ModelPart {
  const profile: { x: number; y: number }[] = [];
  for (let i = 0; i <= 12; i++) { const a = i * Math.PI / 12; profile.push({ x: Math.cos(a) * radius, y: Math.sin(a) * radius }); }
  for (let i = 12; i >= 0; i--) { const a = i * Math.PI / 12; profile.push({ x: Math.cos(a) * (radius - .018), y: Math.sin(a) * (radius - .018) }); }
  return part(name, "extrude", material.glass, position, [1, 1, 1], rotation, { profile, depth, opacity: .32, roughness: .18 });
}

function beltOutline(half: number, radius: number): [number, number][] {
  return [1, -1].flatMap(side => Array.from({ length: 13 }, (_, i): [number, number] => { const a = (side > 0 ? 0 : Math.PI) + i * Math.PI / 12; return [Math.cos(a) * radius, side * half + Math.sin(a) * radius]; }));
}

function uprightBelt(name: string, position: Triple, width: number, half: number, radius: number): ModelPart {
  const value = polygon(name, "#a48c69", beltOutline(half, radius), width, [0, 0, 0], [beltOutline(half, radius - .004)]);
  value.vertices = value.vertices!.map(p => ({ x: p.y - width / 2, y: p.z, z: p.x }));
  value.position = { x: position[0], y: position[1], z: position[2] };
  return value;
}

function settableBladeLoop(): ModelPart {
  const count = 64, vertices: { x: number; y: number; z: number }[] = [], indices: number[] = [];
  for (let ring = 0; ring < 4; ring++) for (let i = 0; i < count; i++) { const a = i * Math.PI / 32, inner = ring > 1, top = ring % 2 === 1; vertices.push({ x: Math.cos(a) * (.85 - (inner ? .002 : 0)), y: top ? .045 + (i % 4 === 0 ? .012 : 0) : 0, z: Math.sin(a) * (.48 - (inner ? .002 : 0)) }); }
  for (let i = 0; i < count; i++) { const j = (i + 1) % count, ob = i, ot = i + count, ib = i + count * 2, it = i + count * 3, nb = j, nt = j + count, ni = j + count * 2, nj = j + count * 3; indices.push(ob, ot, nt, ob, nt, nb, ib, ni, nj, ib, nj, it, ot, it, nj, ot, nj, nt, ob, nb, ni, ob, ni, ib); }
  return part("能穿过夹辊且上沿保留分齿的闭合带锯条", "mesh", material.steel, [0, 1.025, .35], [1, 1, 1], [0, 0, 0], { vertices, indices });
}

